import unittest
from src.csvparse import parse
import src.csvparse as mod


class T(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(parse('a,b,c\n1,2,3\n'), [['a', 'b', 'c'], ['1', '2', '3']])

    def test_quotes(self):
        self.assertEqual(parse('"a,1","say ""hi""","line\nbreak"\n'), [['a,1', 'say "hi"', 'line\nbreak']])

    def test_crlf_and_empty(self):
        self.assertEqual(parse('x,,z\r\n,,\r\n'), [['x', '', 'z'], ['', '', '']])

    def test_unclosed(self):
        with self.assertRaises(ValueError):
            parse('"oops,1\n')

    def test_no_csv_module(self):
        self.assertNotIn('csv', [m.split('.')[0] for m in dir(mod) if not m.startswith('_')])


if __name__ == '__main__':
    unittest.main()
